大家直接使用这个脚本就能快速跳过了
// ==UserScript==
// @name         ysnb 自动跳过验证
// @namespace    http://tampermonkey.net/
// @version      1.0
// @description  打开 ysnb.com.cn 自动通过所有弹窗，直达主页
// @author       You
// @match        https://ysnb.com.cn/*
// @grant        none
// @run-at       document-end
// ==/UserScript==

(function() {
    'use strict';
    // 轮询等待 skip 函数加载完成
    function trySkip() {
        if (typeof skip === 'function') {
            skip();
            console.log('✅ 已自动跳过验证');
        } else {
            setTimeout(trySkip, 300);
        }
    }
    trySkip();
})();
